class vm_thread;

class vm_stack
{
public:
    vm_thread *get_thread() const;
    bool push(const char *, int);
};

class script_library_class
{
public:
    class function
    {
    public:
        enum entry_t
        {
            FIRST_ENTRY,
            RECALL_ENTRY
        };
    };
};

class entity;
typedef entity *vm_entity_t;

class stringx
{
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
};

class vm_executable
{
public:
    const stringx &get_fullname() const;
};

class script_object
{
public:
    class instance
    {
    public:
        const stringx &get_name() const;
    };
};

class vm_thread
{
public:
    script_object::instance *get_instance() const;
    const vm_executable *get_executable() const;
};

stringx operator+(const stringx &, const char *);
stringx operator+(const stringx &, const stringx &);
void error(const stringx &);

extern entity *script_bsp_hit_ent;

class slf_get_bsp_check_hit_ent_t : public script_library_class::function
{
public:
    bool operator()(vm_stack &stack, entry_t entry);
};

bool slf_get_bsp_check_hit_ent_t::operator()(vm_stack &stack, entry_t entry)
{
    vm_entity_t result = static_cast<vm_entity_t>(script_bsp_hit_ent);
    if (!stack.push((char *)&result, sizeof(result)))
        error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname());
    return true;
}
